const tokenBucket = async (key, maxTokens, refillRate) => {
  const now = Date.now();
  const result = await redis.eval(`
    local tokens = tonumber(redis.call("get", KEYS[1]) or ARGV[1])
    local last = tonumber(redis.call("get", KEYS[2]) or ARGV[2])
    local delta = math.max(0, ARGV[2] - last)
    local refill = delta * ARGV[3] / 1000
    tokens = math.min(ARGV[1], tokens + refill)
    if tokens >= 1 then
      tokens = tokens - 1
      redis.call("set", KEYS[1], tokens)
      redis.call("set", KEYS[2], ARGV[2])
      return 1
    end
    return 0
  `, 2, key .. ":tokens", key .. ":ts", maxTokens, now, refillRate);
  return result === 1;
};
